(function () {
    'use strict';

    function decode(binding) {
        const bytes = Uint8Array.from(atob(binding.replace(/-/g, '+').replace(/_/g, '/')), value => value.charCodeAt(0));
        return JSON.parse(new TextDecoder().decode(bytes));
    }

    function encode(input) {
        const bytes = new TextEncoder().encode(JSON.stringify(input));
        return btoa(String.fromCharCode(...bytes)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    }

    function text(tag, value, className) {
        const node = document.createElement(tag);
        node.textContent = value;
        if (className) node.className = className;
        return node;
    }

    function statusPill(item) {
        const pill = text('span', item.status || (item.closed ? 'Zatvoren' : 'Otvoren'), 'wf-hd-badge');
        const color = item['status-color'];
        if (/^#[0-9a-f]{6}$/i.test(color)) pill.style.setProperty('--hd-status-color', color);
        return pill;
    }

    function init(host) {
        const section = host.querySelector('.wf-hd-cards');
        if (!section || section.dataset.hdReady) return;
        section.dataset.hdReady = 'true';
        const overview = section.querySelector('[data-hd-overview]');
        const detail = section.querySelector('[data-hd-detail]');
        const create = section.querySelector('[data-hd-create]');
        const createButton = section.querySelector('[data-hd-new]');
        const form = create.querySelector('[data-wf-case-mode]');
        const scopeButtons = Array.from(section.querySelectorAll('[data-hd-scope]'));
        const select = section.querySelector('[data-hd-status]');
        const feedback = section.querySelector('[data-hd-feedback]');
        const retry = section.querySelector('[data-hd-retry]');
        const list = section.querySelector('[data-hd-list]');
        const pagination = section.querySelector('[data-hd-pagination]');
        const previous = section.querySelector('[data-hd-previous]');
        const next = section.querySelector('[data-hd-next]');
        const back = section.querySelector('[data-hd-back]');
        const cancel = section.querySelector('[data-hd-cancel]');
        const thread = section.querySelector('[data-hd-thread]');
        const previewBinding = host.dataset.wfProviderPreview;
        const preview = Boolean(previewBinding || host.hasAttribute('data-wf-provider-preview-error') || window.parent !== window);
        const sample = previewBinding ? decode(previewBinding) : null;
        let scope = 'open';
        let status = '';
        let page = 1;
        let view = 'list';
        let returnFocus = '';
        let returnScroll = 0;
        let listRequest;
        let threadRequest;
        let completedForm = false;

        async function load(input, signal) {
            const url = new URL(host.dataset.wfProviderUrl, window.location.href);
            url.searchParams.set('wf_input', encode(input));
            const response = await fetch(url, {credentials: 'same-origin', cache: 'no-store', referrerPolicy: 'no-referrer', signal});
            if (!response.ok) throw new Error(String(response.status));
            const result = await response.json();
            if (!result.ok) throw new Error('Provider response');
            return result.data;
        }

        function paint(data) {
            const options = [new Option('Svi statusi', '')];
            for (const entry of data.statuses) {
                options.push(new Option(entry.label + ' (' + entry.count + ')', entry.label));
            }
            if (status && !data.statuses.some(entry => entry.label === status)) options.push(new Option(status + ' (0)', status));
            select.replaceChildren(...options);
            select.value = status;
            page = data.page;
            pagination.hidden = page === 1 && !data['has-next'];
            previous.disabled = page === 1;
            next.disabled = !data['has-next'];
            feedback.textContent = data.total ? 'Ukupno zahteva: ' + data.total : 'Nema zahteva za izabrane filtere.';
            if (data.fallback) feedback.append(' Prikazani su statusi iz evidencije predmeta.');
            list.replaceChildren(...data.items.map(item => {
                const row = document.createElement('li');
                const card = text('button', '', 'wf-hd-card');
                card.type = 'button';
                card.dataset.hdNumber = item.number;
                const meta = text('span', '', 'wf-hd-meta');
                meta.append(text('span', item.number, 'wf-hd-number'));
                if (item['request-type']) meta.append(text('span', item['request-type']));
                const statusRow = text('span', '', 'wf-hd-status-row');
                statusRow.append(statusPill(item));
                if (item.activity) {
                    const date = item.activity.slice(0, 10).split('-').reverse().join('.') + '.';
                    const time = text('time', date + ' ' + item.activity.slice(11, 16), 'wf-hd-meta');
                    time.dateTime = item.activity.replace(' ', 'T');
                    time.title = 'Poslednja vidljiva aktivnost';
                    statusRow.append(time);
                }
                card.append(text('strong', item.title), meta, statusRow);
                card.addEventListener('click', () => navigate('case', item.number));
                row.append(card);
                return row;
            }));
        }

        function previewList() {
            if (!sample) throw new Error('Preview unavailable');
            const rows = sample.items.filter(item => scope === 'all' || !item.closed);
            const counts = new Map();
            rows.forEach(item => counts.set(item.status, (counts.get(item.status) || 0) + 1));
            const items = rows.filter(item => !status || item.status === status);
            return {items, total: items.length, page: 1, 'has-next': false,
                statuses: Array.from(counts, ([label, count]) => ({label, count}))};
        }

        async function updateList() {
            listRequest?.abort();
            listRequest = new AbortController();
            const {signal} = listRequest;
            retry.hidden = true;
            pagination.hidden = true;
            list.replaceChildren();
            feedback.textContent = 'Učitavanje zahteva…';
            try {
                const data = preview ? previewList() : await load({scope, status, page}, signal);
                if (!signal.aborted) paint(data);
            } catch (error) {
                if (signal.aborted) return;
                feedback.textContent = 'Zahtevi trenutno nisu dostupni.';
                select.replaceChildren(new Option('Svi statusi', ''), ...(status ? [new Option(status, status)] : []));
                select.value = status;
                retry.hidden = false;
            }
        }

        function showView(nextView) {
            threadRequest?.abort();
            if (nextView !== 'case') thread.replaceChildren();
            view = nextView;
            overview.hidden = view !== 'list';
            detail.hidden = view !== 'case';
            create.hidden = view !== 'create';
        }

        function showList() {
            showView('list');
            const card = Array.from(list.querySelectorAll('[data-hd-number]')).find(item => item.dataset.hdNumber === returnFocus);
            const focus = returnFocus === 'new' && !createButton.hidden ? createButton : card || select;
            focus.focus({preventScroll: true});
            window.scrollTo(0, returnScroll);
        }

        function rememberList() {
            returnScroll = window.scrollY;
        }

        function navigate(target, number) {
            if (view === 'list') {
                rememberList();
                returnFocus = number || 'new';
                if (window.parent === window) {
                    history.pushState({...history.state, wfHelpDesk: host.dataset.wfInstance, view: target, number}, '');
                }
            }
            if (target === 'case') openCase(number);
            else {
                showView('create');
                if (completedForm) {
                    const mount = form.querySelector('[data-wf-case-mount]');
                    window.ElastycCaseForm?.get(mount)?.restart?.();
                    completedForm = false;
                }
                cancel.focus();
            }
        }

        async function openCase(number) {
            showView('case');
            threadRequest = new AbortController();
            const {signal} = threadRequest;
            back.focus();
            thread.replaceChildren(text('p', 'Učitavanje razgovora…'));
            try {
                let data;
                if (preview) {
                    const item = sample.items.find(row => row.number === number);
                    data = {thread: {...item, company: 'Primer firme', 'opened-at': item.activity.slice(0, 10), messages: [
                        {id: 1, displayname: 'Podrška', usertype: 'P', datum: '2026-01-12 09:30', text: 'Ovo je primer poruke podrške.'}
                    ]}};
                } else {
                    data = await load({case: number}, signal);
                }
                if (signal.aborted) return;
                const item = data.thread;
                if (!window.ElastycCaseMessenger || !item) throw new Error('Conversation unavailable');
                window.ElastycCaseMessenger.mount(thread, {...item, openedAt: item['opened-at']});
                const status = thread.querySelector('.ecm-status');
                if (status) status.replaceWith(statusPill(item));
                if (item['request-type']) thread.querySelector('.ecm-header')?.append(text('p', item['request-type'], 'wf-hd-meta'));
            } catch (error) {
                if (signal.aborted) return;
                thread.replaceChildren(text('p', error.message === '404' ? 'Zahtev više nije dostupan.' : 'Razgovor trenutno nije dostupan.'));
            }
        }

        for (const button of scopeButtons) {
            button.addEventListener('click', () => {
                if (scope === button.dataset.hdScope) return;
                scope = button.dataset.hdScope;
                scopeButtons.forEach(item => item.setAttribute('aria-pressed', String(item === button)));
                page = 1;
                updateList();
            });
        }
        select.addEventListener('change', () => { status = select.value; page = 1; updateList(); });
        previous.addEventListener('click', () => { page--; updateList(); });
        next.addEventListener('click', () => { page++; updateList(); });
        retry.addEventListener('click', updateList);
        createButton.hidden = !form;
        createButton.addEventListener('click', () => navigate('create'));
        form?.addEventListener('elastyc:case-form-success', event => {
            const number = event.detail?.result?.acckey;
            if (preview || !/^[0-9]{2}S[0-9]{8}$/.test(number)) return;
            if (history.state?.wfHelpDesk === host.dataset.wfInstance) {
                history.replaceState({...history.state, view: 'case', number}, '');
            }
            completedForm = true;
            updateList();
            openCase(number);
        });
        function goBack() {
            if (window.parent === window && history.state?.wfHelpDesk === host.dataset.wfInstance) history.back();
            else showList();
        }
        back.addEventListener('click', goBack);
        cancel.addEventListener('click', goBack);
        if (window.parent === window) {
            window.addEventListener('popstate', event => {
                if (event.state?.wfHelpDesk === host.dataset.wfInstance) {
                    if (view === 'list') rememberList();
                    navigateFromHistory(event.state);
                } else if (view !== 'list') showList();
            });
            window.addEventListener('pageshow', event => {
                if (event.persisted) { showView('list'); updateList(); }
            });
        }
        function navigateFromHistory(state) {
            if (state.view === 'case' && state.number) {
                returnFocus = state.number;
                openCase(state.number);
            } else if (state.view === 'create' && form) {
                returnFocus = 'new';
                showView('create');
                cancel.focus();
            }
        }
        if (window.parent === window && history.state?.wfHelpDesk === host.dataset.wfInstance) {
            const {wfHelpDesk, view, number, ...previousState} = history.state;
            history.replaceState(previousState, '');
        }
        updateList();
    }

    document.querySelectorAll('[data-wf-component="help-desk"]').forEach(init);
}());
